{
 "summary": "The Lean file proves two things. First, there is a finite connected bipartite 2-degenerate graph H on Fin q such that, under each of its 2-colourings, both colour classes contain a vertex of degree ≥ 3, and there are constants c, ε > 0 with c·n^{3/2+ε} ≤ ex(n,H) for all sufficiently large n. Second, Erdős's degeneracy conjecture fails: it is not true that every bipartite r-degenerate H (r > 0) has ex(n,H) = O(n^{2−1/r}). Both statements faithfully match Theorem 1.2 and its stated corollary. The main caveat is coverage: Theorem 1.1 (failure of compactness) is not formalized at all.",
 "glossary": [
  {"decl": "neighborsWithin", "line": 8, "plain": "N_G(v) ∩ s, the neighbours of v inside the finite set s", "standard_concept": "neighbourhood restricted to a vertex subset", "matches_standard": "yes", "note": ""},
  {"decl": "IsDegenerate", "line": 13, "plain": "Every nonempty finite vertex set s contains a vertex with at most r neighbours in s, i.e. every nonempty induced subgraph has minimum degree ≤ r", "standard_concept": "r-degenerate graph", "matches_standard": "yes", "note": "The paper says 'subgraph' rather than 'induced subgraph'. The two are equivalent, since passing to a subgraph only lowers degrees."},
  {"decl": "IsTwoDegenerate", "line": 17, "plain": "IsDegenerate 2", "standard_concept": "2-degenerate", "matches_standard": "yes", "note": ""},
  {"decl": "DegeneracyConjectureStatement", "line": 20, "plain": "For all r > 0 and every bipartite r-degenerate graph H on Fin q, ex(n,H) = O(n^{2−1/r}) as n → ∞", "standard_concept": "Erdős degeneracy conjecture (3)", "matches_standard": "yes", "note": ""}
 ],
 "lean_claims": [
  {"theorem": "twoDegenerateExtremalCounterexample", "line": 28, "plain": "There exist q and a graph H on Fin q with these properties: H is connected, bipartite and 2-degenerate; for every proper 2-colouring of H and each colour, some vertex of that colour has degree > 2; and there exist reals c > 0, ε > 0 such that for all sufficiently large n, c·n^{3/2+ε} ≤ ex(n,H)."},
  {"theorem": "not_erdos_146", "line": 43, "plain": "There exist r > 0 and a bipartite r-degenerate graph H on some Fin q such that ex(n,H) is not O(n^{2−1/r})."}
 ],
 "paper_claims": [
  {"ref": "Theorem 1.1", "plain": "There is a finite nonempty family F of connected bipartite graphs, each containing a cycle, with ex(n,F) = O(n^{4/3−1/48}) and ex(n,F) = Ω(n^{4/3}) for each F ∈ F."},
  {"ref": "Theorem 1.2", "plain": "There exist a fixed connected bipartite 2-degenerate graph H and constants c, ε > 0 such that ex(n,H) ≥ c·n^{3/2+ε} for all sufficiently large n."},
  {"ref": "Abstract/Intro (Erdős degeneracy conjecture disproved)", "plain": "The conjecture that every bipartite r-degenerate H has ex(n,H) = O(n^{2−1/r}) is false, already for r = 2."}
 ],
