  {"paper_ref": "Theorem 1.2", "lean_theorem": "twoDegenerateExtremalCounterexample", "relation": "lean_stronger", "why": "Same claim, plus an extra condition that both bipartition classes have maximum degree ≥ 3."},
  {"paper_ref": "Abstract/Intro (Erdős degeneracy conjecture disproved)", "lean_theorem": "not_erdos_146", "relation": "equivalent", "why": "The negation of the conjecture exactly as stated in (3)."}
 ],
